parameters.jsCode:
const raw = $json.output;

if (!raw) {
  throw new Error("AI Agent output is empty or missing.");
}

let data;

try {
  // Parse the JSON string returned by the AI Agent
  data = typeof raw === "string" ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error(
    "AI Agent output is not valid JSON. Check whether the JSON is complete. Details: " +
    error.message
  );
}

// Return individual fields that n8n can map
return {
  json: {
    customer_name: data.customer_name ?? "",
    customer_email: data.customer_email ?? "",
    customer_phone: data.customer_phone ?? "",
    customer_message: data.customer_message ?? "",
    customer_summary: data.customer_summary ?? "",
    email_subject: data.email_subject ?? "",
    email_body: data.email_body ?? "",
    airtable_log_status: data.airtable_log_status ?? "Pending",
    needs_human_follow_up: data.needs_human_follow_up ?? false
  }
};
